import sys; sys.path.insert(0,'iter_0/candidate_5/scratch/s')
from screen import *
L=LL(0.9)
def q_of(lam):
    prior=np.where(isrule,np.log(lam/NR),np.log((1-lam)/5050))
    lp=L+prior; lp-=logsumexp(lp,axis=1,keepdims=True)
    return np.clip((np.exp(lp)@M)[si,tg],1e-9,1-1e-9)
base=pred(0.34,0,0,0.9,0.006,1.0)
def run(name,fn,x0):
    r=minimize(lambda t:nll(fn(t)),x0,method='Nelder-Mead',options=dict(maxiter=800))
    p=fn(r.x); print(name,round(r.fun,2),np.round(r.x,3),'rmse',np.sqrt(((p-base)**2).mean()).round(4))
run('inc',lambda t:np.clip((1-expit(t[1]))*q_of(expit(t[0]))+expit(t[1]),1e-6,1-1e-6),[-0.6,-5])
def power(t):
    q=q_of(expit(t[0]))**np.exp(t[2]); return np.clip((1-expit(t[1]))*q+expit(t[1]),1e-6,1-1e-6)
run('power q^g',power,[-0.6,-5,0])
def gain(t):
    q=q_of(expit(t[0])); lo=np.log(q)-np.log1p(-q); q=expit(np.exp(t[2])*lo)
    return np.clip((1-expit(t[1]))*q+expit(t[1]),1e-6,1-1e-6)
run('logodds gain',gain,[-0.6,-5,0])
